import math

import pytest


def isqrt(n: int) -> int:
    """Return the integer square root of n: the largest r with r*r <= n.

    Contract (to be stated with assert statements in the body):
    - Precondition: n >= 0.
    - Postcondition: the result r satisfies r*r <= n < (r+1)*(r+1).
    """
    assert n >= 0, "n must be non-negative"
    if n == 0:
        r = 0
    else:
        # Newton's method on integers, starting from a power of two >= sqrt(n).
        x = 1 << ((n.bit_length() + 1) // 2)
        while True:
            y = (x + n // x) // 2
            if y >= x:
                break
            x = y
        r = x
    assert r * r <= n < (r + 1) * (r + 1)
    return r


def test_small_values() -> None:
    assert isqrt(0) == 0
    assert isqrt(1) == 1
    assert isqrt(2) == 1
    assert isqrt(3) == 1
    assert isqrt(4) == 2
    assert isqrt(8) == 2
    assert isqrt(9) == 3
    assert isqrt(15) == 3
    assert isqrt(16) == 4


@pytest.mark.parametrize("r", [0, 1, 2, 3, 10, 99, 1000, 123456789])
def test_perfect_squares(r: int) -> None:
    assert isqrt(r * r) == r


@pytest.mark.parametrize("r", [1, 2, 3, 10, 99, 1000, 123456789])
def test_around_perfect_squares(r: int) -> None:
    assert isqrt(r * r - 1) == r - 1
    assert isqrt(r * r + 1) == r
    assert isqrt((r + 1) * (r + 1) - 1) == r


def test_large_values() -> None:
    assert isqrt(10**40) == 10**20
    assert isqrt(10**40 - 1) == 10**20 - 1
    assert isqrt(10**40 + 1) == 10**20
    assert isqrt(2**200) == 2**100


def test_postcondition_property() -> None:
    for n in range(0, 2000):
        r = isqrt(n)
        assert r * r <= n < (r + 1) * (r + 1)


def test_matches_math_isqrt() -> None:
    for n in [0, 1, 5, 17, 10**6, 10**6 + 1, 2**64, 2**64 - 1, 3**100]:
        assert isqrt(n) == math.isqrt(n)


@pytest.mark.parametrize("n", [-1, -2, -100, -(10**30)])
def test_negative_violates_precondition(n: int) -> None:
    with pytest.raises(AssertionError):
        isqrt(n)
